type SetupIntentObservation struct {
	// The list of payment method types to allow for this SetupIntent. Stripe will only use methods in this list when determining the payment methods to offer.
	AllowedPaymentMethodTypes *JSON `json:"allowedPaymentMethodTypes,omitempty"`

	// ID of the Connect application that created the SetupIntent.
	Application *string `json:"application,omitempty"`

	// If present, the SetupIntent's payment method will be attached to the in-context Stripe Account.
	//
	// It can only be used for this Stripe Account’s own money movement flows like InboundTransfer and OutboundTransfers. It cannot be set to true when setting up a PaymentMethod for a Customer, and defaults to false when attaching a PaymentMethod to a Customer.
	AttachToSelf *bool `json:"attachToSelf,omitempty"`

	// Settings for dynamic payment methods compatible with this Setup Intent
	AutomaticPaymentMethods *JSON `json:"automaticPaymentMethods,omitempty"`

	// Reason for cancellation of this SetupIntent, one of `abandoned`, `requested_by_customer`, or `duplicate`.
	CancellationReason *string `json:"cancellationReason,omitempty"`

	// Time at which the object was created. Measured in seconds since the Unix epoch.
	Created *int64 `json:"created,omitempty"`

	// ID of the Customer this SetupIntent belongs to, if one exists.
	//
	// If present, the SetupIntent's payment method will be attached to the Customer on successful setup. Payment methods attached to other Customers cannot be used with this SetupIntent.
	Customer *string `json:"customer,omitempty"`

	// ID of the Account this SetupIntent belongs to, if one exists.
	//
	// If present, the SetupIntent's payment method will be attached to the Account on successful setup. Payment methods attached to other Accounts cannot be used with this SetupIntent.
	CustomerAccount *string `json:"customerAccount,omitempty"`

	// An arbitrary string attached to the object. Often useful for displaying to users.
	Description *string `json:"description,omitempty"`

	// Payment method types that are excluded from this SetupIntent.
	ExcludedPaymentMethodTypes *JSON `json:"excludedPaymentMethodTypes,omitempty"`

	// Indicates the directions of money movement for which this payment method is intended to be used.
	//
	// Include `inbound` if you intend to use the payment method as the origin to pull funds from. Include `outbound` if you intend to use the payment method as the destination to send funds to. You can include both if you intend to use the payment method for both purposes.
	FlowDirections *JSON `json:"flowDirections,omitempty"`

	// Unique identifier for the object.
	ID *string `json:"id,omitempty"`

	// The error encountered in the previous SetupIntent confirmation.
	LastSetupError *JSON `json:"lastSetupError,omitempty"`

	// The most recent SetupAttempt for this SetupIntent.
	LatestAttempt *string `json:"latestAttempt,omitempty"`

	// If the object exists in live mode, the value is `true`. If the object exists in test mode, the value is `false`.
	Livemode *bool `json:"livemode,omitempty"`

	ManagedPayments *JSON `json:"managedPayments,omitempty"`

	// ID of the multi use Mandate generated by the SetupIntent.
	Mandate *string `json:"mandate,omitempty"`

	// Set of [key-value pairs](https://docs.stripe.com/api/metadata) that you can attach to an object. This can be useful for storing additional information about the object in a structured format.
	Metadata map[string]string `json:"metadata,omitempty"`

	// If present, this property tells you what actions you need to take in order for your customer to continue payment setup.
	NextAction *JSON `json:"nextAction,omitempty"`

	// String representing the object's type. Objects of the same type share the same value.
	Object *string `json:"object,omitempty"`

	// The account (if any) for which the setup is intended.
	OnBehalfOf *string `json:"onBehalfOf,omitempty"`

	// ID of the payment method used with this SetupIntent. If the payment method is `card_present` and isn't a digital wallet, then the [generated_card](https://docs.stripe.com/api/setup_attempts/object#setup_attempt_object-payment_method_details-card_present-generated_card) associated with the `latest_attempt` is attached to the Customer instead.
	PaymentMethod *string `json:"paymentMethod,omitempty"`

	// Information about the [payment method configuration](https://docs.stripe.com/api/payment_method_configurations) used for this Setup Intent.
	PaymentMethodConfigurationDetails *JSON `json:"paymentMethodConfigurationDetails,omitempty"`

	// Payment method-specific configuration for this SetupIntent.
	PaymentMethodOptions *JSON `json:"paymentMethodOptions,omitempty"`

	// The list of payment method types (e.g. card) that this SetupIntent is allowed to set up. A list of valid payment method types can be found [here](https://docs.stripe.com/api/payment_methods/object#payment_method_object-type).
	PaymentMethodTypes *JSON `json:"paymentMethodTypes,omitempty"`

	// ID of the single_use Mandate generated by the SetupIntent.
	SingleUseMandate *string `json:"singleUseMandate,omitempty"`

	// [Status](https://docs.stripe.com/payments/intents#intent-statuses) of this SetupIntent, one of `requires_payment_method`, `requires_confirmation`, `requires_action`, `processing`, `canceled`, or `succeeded`.
	Status *string `json:"status,omitempty"`

	// Indicates how the payment method is intended to be used in the future.
	//
	// Use `on_session` if you intend to only reuse the payment method when the customer is in your checkout flow. Use `off_session` if your customer may or may not be in your checkout flow. If not provided, this value defaults to `off_session`.
	Usage *string `json:"usage,omitempty"`
}

